from collections import defaultdict, deque

def numBusesToDestination(routes, S, T):
    if S == T:
        return 0

    # Create a graph where each bus stop is a node and there is an edge between two nodes if they are served by the same bus
    graph = defaultdict(list)
    for i, route in enumerate(routes):
        for stop in route:
            graph[stop].append(i)

    # Use BFS to find the shortest path from S to T
    queue = deque([S])
    visited_stops = set([S])
    visited_routes = set()
    buses_taken = 0

    while queue:
        buses_taken += 1
        for _ in range(len(queue)):
            current_stop = queue.popleft()
            for route_index in graph[current_stop]:
                if route_index not in visited_routes:
                    visited_routes.add(route_index)
                    for next_stop in routes[route_index]:
                        if next_stop == T:
                            return buses_taken
                        if next_stop not in visited_stops:
                            visited_stops.add(next_stop)
                            queue.append(next_stop)
    return -1
